  WHERE name ILIKE 'Toán cao cấp 1'
)
SELECT * FROM cs ORDER BY gpa_avg;

SELECT AVG(fail_rate_avg)::float AS avg_fail_rate_over_all
FROM vw_course_stats
WHERE total_students >= 5;

